# ruff: noqa: INP001
import argparse
from pathlib import Path

import regex

PROPERTIES = {
    "EMOJI": "Emoji",
    "MODIFIER": "Emoji_Modifier",
    "PRESENTATION": "Emoji_Presentation",
    "REGIONAL": "Regional_Indicator",
}


def render() -> str:
    lines = [
        "// Generated by rust-backend/tools/generate_markdown_emoji_data.py.",
        "// These ranges belong to the Python reference renderer, not Rust regex.",
        "",
        f'pub const REGEX_VERSION: &str = "{regex.__version__}";',
    ]
    for symbol, name in PROPERTIES.items():
        expression = regex.compile(r"\p{" + name + "}")
        ranges: list[tuple[int, int]] = []
        for point in range(0x110000):
            if 0xD800 <= point <= 0xDFFF or not expression.fullmatch(chr(point)):
                continue
            if ranges and point == ranges[-1][1] + 1:
                ranges[-1] = (ranges[-1][0], point)
            else:
                ranges.append((point, point))
        lines.append("")
        if len(ranges) == 1:
            start, end = ranges[0]
            lines.append(f"pub(super) const {symbol}: &[(u32, u32)] = &[(0x{start:x}, 0x{end:x})];")
        else:
            lines.append(f"pub(super) const {symbol}: &[(u32, u32)] = &[")
            lines.extend(f"    (0x{start:x}, 0x{end:x})," for start, end in ranges)
            lines.append("];")
    return "\n".join(lines) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Generate reference Unicode emoji properties offline."
    )
    parser.add_argument("--check", action="store_true")
    parser.add_argument(
        "--output",
        type=Path,
        default=Path(__file__).resolve().parents[1] / "src/markdown_emoji_data.rs",
    )
    args = parser.parse_args()
    source = render()
    if args.check:
        if args.output.read_text() != source:
            parser.error(
                "emoji properties differ; regenerate with the provisioned regex dependency"
            )
    else:
        args.output.write_text(source)


if __name__ == "__main__":
    main()
